custom_qss:
/* ============================================================
   MOIRE — reflect-mode interference banding. spread:reflect
   mirrors the gradient at every tile boundary instead of repeating
   it, so a plain ramp becomes a zigzag / moire pattern, not stripes.
   The window tiles coarsely on one diagonal, the docks finely on the
   other, so overlapping surfaces interfere and appear to vibrate.
   Cold cyan-teal + violet duotone. Inverted selection.
   ============================================================ */

* { color: #daf2f7; letter-spacing: 1px; }
QAbstractScrollArea, QFrame, QStackedWidget, QScrollArea, QTabWidget, QWidget {
    background: transparent; border: none;
}

/* window: coarse interference wave */
QMainWindow { background: qlineargradient(x1:0, y1:0, x2:0.22, y2:0.22, spread:reflect, stop:0 #0f3a44, stop:1 #04080c) !important; border: none; }
QDialog { background: #04080c !important; border: 2px solid #12303d; }

/* menubar */
QMenuBar { background: #070e14 !important; border: none; border-bottom: 1px solid #12303d; }
QMenuBar::item { padding: 5px 14px; background: transparent !important; color: #5a8896; letter-spacing: 3px; }
QMenuBar::item:selected { background: #0f1c26 !important; color: #19d3d3; }
QMenuBar::item:disabled { color: #3a5a66; }

/* popup menus */
QMenu { background: #0a1218 !important; border: 2px solid #12303d; padding: 6px; }
QMenu::item { padding: 7px 26px 7px 14px; background: transparent !important; color: #daf2f7; letter-spacing: 2px; }
QMenu::item:selected { background: #04080c !important; color: #5a8896; border-left: 3px solid #7a5cff; }
QMenu::item:disabled { color: #3a5a66; }
QMenu::separator { height: 2px; background: #12303d; margin: 6px 10px; }

/* toolbar */
QToolBar { background: #070e14 !important; border: none; border-bottom: 1px solid #12303d; spacing: 3px; padding: 4px; }
QToolBar::separator { background: #12303d; width: 1px; margin: 6px 5px; }
QToolBar QToolButton, QToolButton { background: transparent !important; padding: 6px 12px; border: 1px solid transparent; color: #8fc4d0; letter-spacing: 2px; font-size: 12px; }
QToolBar QToolButton:hover, QToolButton:hover { background: #0f1c26 !important; border: 1px solid #1a4453; color: #19d3d3; }
QToolBar QToolButton:checked, QToolBar QToolButton:pressed,
QToolButton:checked, QToolButton:pressed { background: #04080c !important; border: 1px solid #7a5cff; color: #5a8896; }

/* buttons: double-border, violet selected (inverted = dim) */
QPushButton { background: #0a1218 !important; border: 2px solid #12303d; border-radius: 2px; padding: 8px 22px; color: #daf2f7; font-weight: 600; letter-spacing: 3px; font-size: 12px; }
QPushButton:hover { background: #0f1c26 !important; border: 2px solid #19d3d3; color: #19d3d3; }
QPushButton:pressed { background: #19d3d3 !important; color: #04080c; }
QPushButton:checked { background: #04080c !important; border: 2px solid #7a5cff; color: #5a8896; }
QPushButton:default { border: 2px solid #19d3d3; }
QPushButton:disabled { background: #070e14 !important; color: #3a5a66; border: 2px solid #12303d; }

/* inputs */
QLineEdit, QSpinBox, QDoubleSpinBox, QTextEdit, QPlainTextEdit { background: #02060a !important; border: 2px solid #12303d; border-radius: 2px; padding: 7px 12px; color: #19d3d3; letter-spacing: 2px; font-size: 12px; selection-background-color: #7a5cff; selection-color: #ffffff; }
QLineEdit:focus, QSpinBox:focus, QDoubleSpinBox:focus, QTextEdit:focus, QPlainTextEdit:focus { border: 2px solid #19d3d3; }
QLineEdit:disabled, QSpinBox:disabled, QDoubleSpinBox:disabled, QTextEdit:disabled, QPlainTextEdit:disabled { color: #3a5a66; }
QSpinBox::up-button, QSpinBox::down-button, QDoubleSpinBox::up-button, QDoubleSpinBox::down-button { background: transparent !important; border: none; width: 16px; }

QComboBox { background: #02060a !important; border: 2px solid #12303d; border-radius: 2px; padding: 7px 12px; color: #daf2f7; letter-spacing: 2px; font-size: 12px; }
QComboBox:hover { border: 2px solid #1a4453; }
QComboBox:focus { border: 2px solid #19d3d3; }
QComboBox::drop-down { border: none; background: transparent !important; width: 18px; }
QComboBox QAbstractItemView { background: #0a1218 !important; border: 2px solid #12303d; padding: 5px; selection-background-color: #04080c; selection-color: #5a8896; }

QCheckBox, QRadioButton { color: #daf2f7; background: transparent !important; padding: 3px; letter-spacing: 2px; }
QCheckBox::indicator, QRadioButton::indicator { width: 16px; height: 16px; border-radius: 2px; background: #02060a !important; border: 2px solid #1a4453; }
QRadioButton::indicator { border-radius: 8px; }
QCheckBox::indicator:hover, QRadioButton::indicator:hover { border: 2px solid #19d3d3; }
QCheckBox::indicator:checked, QRadioButton::indicator:checked { background: #7a5cff !important; border: 2px solid #7a5cff; }

QTabBar::tab { background: transparent !important; color: #5a8896; padding: 9px 18px; border: 1px solid transparent; border-bottom: 2px solid transparent; letter-spacing: 3px; }
QTabBar::tab:hover { color: #daf2f7; }
QTabBar::tab:selected { color: #5a8896; border: 1px solid #7a5cff; border-bottom: 2px solid #7a5cff; }
QTabWidget::pane { border: none; border-top: 2px solid #12303d; }

/* docks: FINE interference on the opposite diagonal — beats against the window */
QDockWidget { background: qlineargradient(x1:0, y1:1, x2:0.13, y2:0, spread:reflect, stop:0 #12333d, stop:1 #02060a) !important; border: 2px solid #12303d; border-radius: 2px; }
QDockWidget::title { background: #070e14 !important; border: none; border-bottom: 2px solid #12303d; border-left: 4px solid #19d3d3; padding: 7px 12px; color: #8fc4d0; font-weight: 700; letter-spacing: 2px; }
QDockWidget::close-button, QDockWidget::float-button { background: transparent !important; border: 1px solid transparent; border-radius: 2px; padding: 3px; icon-size: 18px; }
QDockWidget::close-button:hover, QDockWidget::float-button:hover { background: #0f1c26 !important; }

QGroupBox { background: transparent !important; border: 2px solid #12303d; border-radius: 2px; margin-top: 13px; padding-top: 11px; }
QGroupBox::title { subcontrol-origin: margin; subcontrol-position: top left; padding: 0 10px; color: #7a5cff; font-weight: 700; letter-spacing: 2px; background: #04080c; }

/* item views: INVERTED selection */
QAbstractItemView { background: #02060a !important; border: 2px solid #12303d; border-radius: 2px; outline: none; alternate-background-color: #070e14; selection-background-color: #04080c; selection-color: #5a8896; }
QAbstractItemView::item { padding: 6px 12px; border: none; border-left: 3px solid transparent; border-bottom: 1px solid #12303d; color: #daf2f7; letter-spacing: 1px; }
QAbstractItemView::item:hover { background: #0f1c26 !important; color: #19d3d3; }
QAbstractItemView::item:selected { background: #04080c !important; color: #5a8896; border-left: 3px solid #7a5cff; }
QTreeView::branch { background: transparent !important; }
QHeaderView::section { background: #070e14 !important; border: none; border-bottom: 2px solid #12303d; padding: 7px 12px; color: #8fc4d0; font-weight: 700; letter-spacing: 3px; }

QScrollBar:vertical { background: #02060a; width: 11px; margin: 0; border: none; }
QScrollBar::handle:vertical { background: #1a4453; border-radius: 2px; min-height: 32px; }
QScrollBar::handle:vertical:hover { background: #19d3d3; }
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0; border: none; background: none; }
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background: none; }
QScrollBar:horizontal { background: #02060a; height: 11px; margin: 0; border: none; }
QScrollBar::handle:horizontal { background: #1a4453; border-radius: 2px; min-width: 32px; }
QScrollBar::handle:horizontal:hover { background: #19d3d3; }
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal { width: 0; border: none; background: none; }
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal { background: none; }
QScrollBar::corner { background: none; }

QSlider::groove:horizontal { background: #02060a; border: 2px solid #12303d; height: 8px; border-radius: 2px; }
QSlider::sub-page:horizontal { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #19d3d3, stop:1 #7a5cff); border-radius: 2px; }
QSlider::add-page:horizontal { background: #02060a; border-radius: 2px; }
QSlider::handle:horizontal { background: #19d3d3; width: 14px; height: 16px; margin: -6px 0; border: 2px solid #04080c; border-radius: 2px; }
QSlider::handle:horizontal:hover { background: #a08fff; }
QSlider::groove:vertical { background: #02060a; border: 2px solid #12303d; width: 8px; border-radius: 2px; }
QSlider::sub-page:vertical { background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #19d3d3, stop:1 #7a5cff); border-radius: 2px; }
QSlider::handle:vertical { background: #19d3d3; width: 16px; height: 14px; margin: 0 -6px; border: 2px solid #04080c; border-radius: 2px; }

QProgressBar { background: #02060a; border: 2px solid #12303d; border-radius: 2px; text-align: center; color: #8fc4d0; font-size: 11px; letter-spacing: 3px; min-height: 16px; }
QProgressBar::chunk { background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #19d3d3, stop:0.5 #7a5cff, stop:1 #19d3d3); border-radius: 2px; }

QStatusBar { background: #070e14 !important; border-top: 2px solid #12303d; color: #5a8896; font-size: 11px; letter-spacing: 2px; }
QStatusBar::item { border: none; }
QToolTip { background: #0a1218 !important; border: 2px solid #19d3d3; border-radius: 2px; padding: 6px 12px; color: #daf2f7; }
QSplitter::handle { background: #12303d; }
QSplitter::handle:hover { background: #19d3d3; }
QListView, QListWidget, QTreeWidget, QTableWidget { background: #02060a !important; border: 2px solid #12303d; border-radius: 2px; outline: none; }
